variants.code_sketch:
sealed abstract class Suit(val key: String)
object Suit {
  case object Clubs    extends Suit("clubs")
  case object Diamonds extends Suit("diamonds")
  case object Hearts   extends Suit("hearts")
  case object Spades   extends Suit("spades")
}

// exhaustive because the hierarchy is sealed:
def label(s: Suit): String = s match {
  case Suit.Clubs => "clubs"
  case _          => "other"
}
